INSERT INTO _fleet_sync_mail_items(item_id,stream,seq,live,payload_bytes,settlement_bytes,record,capacity_slot) VALUES(?1,?2,CAST(?3 AS INTEGER),CAST(?4 AS INTEGER),CAST(?5 AS INTEGER),CAST(?6 AS INTEGER),?7,CAST(?8 AS INTEGER)) ON CONFLICT(item_id) DO UPDATE SET live=excluded.live,payload_bytes=excluded.payload_bytes,settlement_bytes=excluded.settlement_bytes,record=excluded.record,capacity_slot=excluded.capacity_slot;
